  for (let i = 0; i < 6; i += 1) { orbitOf2.push(v); v = (v * 2) % 9 || 9 }
  const twoIsPrimitiveRoot = new Set(orbitOf2).size === 6 && units.every((u) => orbitOf2.includes(u)) // order 6
  const trinityIsNonUnits = nonUnits.join(',') === '3,6,9'
